import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"The Record Data Type","description":"","frontmatter":{},"headers":[],"relativePath":"records-data-access-filtering-and-validation/record-data-type.md","filePath":"records-data-access-filtering-and-validation/record-data-type.md"}`),a={name:`records-data-access-filtering-and-validation/record-data-type.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="the-record-data-type" tabindex="-1">The Record Data Type <a class="header-anchor" href="#the-record-data-type" aria-label="Permalink to “The Record Data Type”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>The <code>Record</code> data type is used to interact with data stored in Business Central tables.</p><p>It allows us to retrieve, read, insert, modify, and delete records in database tables.</p><p>Think of a record variable as an object through which AL code can interact with a particular table.</p><p>For example, if we want to work with customer records, we declare a variable of type <code>Record Customer</code>.</p><h2 id="declaring-record-variables" tabindex="-1">Declaring Record Variables <a class="header-anchor" href="#declaring-record-variables" aria-label="Permalink to “Declaring Record Variables”">​</a></h2><p>We declare record variables using the <code>Record</code> keyword, followed by the name of the table we want to interact with.</p><h3 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to “Syntax”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>VariableName: Record TableName;</span></span></code></pre></div><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    CustomerRec: Record Customer;</span></span>
<span class="line"><span>    ProductRec: Record Product;</span></span>
<span class="line"><span>    EmployeeRec: Record Employee;</span></span></code></pre></div><p>In this example:</p><ul><li><code>CustomerRec</code> represents a record from the Customer table.</li><li><code>ProductRec</code> represents a record from the Product table.</li><li><code>EmployeeRec</code> represents a record from the Employee table.</li></ul><p>Notice that we don&#39;t need to create a separate variable for every field in the table. The record variable gives us access to the table&#39;s fields.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    ProductRec: Record Product;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    ProductRec.Name := &#39;Laptop&#39;;</span></span>
<span class="line"><span>    ProductRec.Inventory := 20;</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Here, we are assigning values to fields through the <code>ProductRec</code> variable.</p><p><strong>Important:</strong> Assigning values to a record variable does not automatically insert or update a database record. The changes are initially held in the record variable and must be explicitly saved when necessary.</p><h2 id="accessing-record-fields" tabindex="-1">Accessing Record Fields <a class="header-anchor" href="#accessing-record-fields" aria-label="Permalink to “Accessing Record Fields”">​</a></h2><p>We access fields through the record variable using dot notation.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    ProductRec: Record Product;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    ProductRec.Name := &#39;Laptop&#39;;</span></span>
<span class="line"><span>    ProductRec.Inventory := 20;</span></span>
<span class="line"><span>    ProductRec.&quot;Unit Price&quot; := 1500;</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>We can also read field values:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Message(&#39;Product: %1&#39;, ProductRec.Name);</span></span></code></pre></div><p>This is similar to accessing properties of an object in languages such as C# or JavaScript.</p><p>Notice that fields containing spaces must be enclosed in double quotes.</p><h2 id="record-variables-and-database-operations" tabindex="-1">Record Variables and Database Operations <a class="header-anchor" href="#record-variables-and-database-operations" aria-label="Permalink to “Record Variables and Database Operations”">​</a></h2><p>A record variable provides methods for interacting with the underlying table.</p><p>Some important operations include:</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>Get()</code></td><td>Retrieves a record using its primary key.</td></tr><tr><td><code>FindFirst()</code></td><td>Retrieves the first record matching the current filters and sorting.</td></tr><tr><td><code>FindLast()</code></td><td>Retrieves the last matching record.</td></tr><tr><td><code>FindSet()</code></td><td>Retrieves a set of records for processing.</td></tr><tr><td><code>Insert()</code></td><td>Inserts a new record into the table.</td></tr><tr><td><code>Modify()</code></td><td>Saves changes to an existing record.</td></tr><tr><td><code>Delete()</code></td><td>Deletes the current record.</td></tr><tr><td><code>Count()</code></td><td>Counts the records matching the current filters.</td></tr><tr><td><code>IsEmpty()</code></td><td>Checks whether the current filtered set contains records.</td></tr></tbody></table><p>We&#39;ll explore these methods individually in the upcoming topics.</p><h2 id="working-with-records-a-simple-example" tabindex="-1">Working with Records: A Simple Example <a class="header-anchor" href="#working-with-records-a-simple-example" aria-label="Permalink to “Working with Records: A Simple Example”">​</a></h2><p>Let&#39;s create a codeunit that retrieves a product record and displays its information.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50100 ProductManager</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnRun()</span></span>
<span class="line"><span>    var</span></span>
<span class="line"><span>        ProductRec: Record Product;</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        if ProductRec.Get(&#39;PROD001&#39;) then</span></span>
<span class="line"><span>            Message(</span></span>
<span class="line"><span>                &#39;Product: %1, Inventory: %2&#39;,</span></span>
<span class="line"><span>                ProductRec.Name,</span></span>
<span class="line"><span>                ProductRec.Inventory</span></span>
<span class="line"><span>            )</span></span>
<span class="line"><span>        else</span></span>
<span class="line"><span>            Message(&#39;Product not found.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here:</p><ol><li>We declare a record variable for the Product table.</li><li>We call <code>Get()</code> to retrieve the product with primary key <code>PROD001</code>.</li><li>If the record exists, we access its fields and display their values.</li><li>Otherwise, we display a message indicating that the product was not found.</li></ol><p><strong>Note:</strong> The example assumes <code>Product</code> has a primary key that accepts <code>PROD001</code> as its value. The arguments passed to <code>Get()</code> must correspond to the table&#39;s primary key fields.</p><h2 id="system-defined-record-variables" tabindex="-1">System-Defined Record Variables <a class="header-anchor" href="#system-defined-record-variables" aria-label="Permalink to “System-Defined Record Variables”">​</a></h2><p>You have already encountered a record variable called <code>Rec</code> when working with pages.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(Name; Rec.Name)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ApplicationArea = All;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>Rec</code> is a system-defined record variable representing the current record being displayed or processed by the page.</p><p>You don&#39;t need to declare it yourself.</p><p>You can also encounter <code>xRec</code>, which represents the previous version of a record in relevant table and page triggers.</p><p>These are system-provided variables, unlike the record variables we explicitly declare.</p><h2 id="important-things-to-remember" tabindex="-1">Important Things to Remember <a class="header-anchor" href="#important-things-to-remember" aria-label="Permalink to “Important Things to Remember”">​</a></h2><ul><li>The <code>Record</code> data type allows us to interact with Business Central tables.</li><li>Declare record variables using <code>VariableName: Record TableName;</code>.</li><li>Use dot notation to access table fields.</li><li>Assigning values to a record variable does not automatically save them to the database.</li><li>Use record methods such as <code>Get()</code>, <code>FindSet()</code>, <code>Insert()</code>, <code>Modify()</code>, and <code>Delete()</code> to perform database operations.</li><li><code>Rec</code> and <code>xRec</code> are examples of system-defined record variables.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-data-type" target="_blank" rel="noreferrer">Record Data Type – Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-get-method" target="_blank" rel="noreferrer">Record.Get() Method</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-findset-method" target="_blank" rel="noreferrer">Record.FindSet() Method</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-insert-method" target="_blank" rel="noreferrer">Record.Insert() Method</a></li></ul>`,49)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};